{"t":"say","text":"I'll draw ACK for 20 Java microservices, Cloud-native API Gateway as the entry, MSE Nacos for discovery and config, RocketMQ, Tair and PolarDB."}
{"t":"req","text":"Java microservices on Kubernetes"}
{"t":"plan","products":["users","dns","cloud-native-api-gateway","waf","ack","acr","mse","rocketmq","tair","polardb","arms","sls"]}
{"t":"assume","id":"exposure","text":"Public-facing APIs","alt":"Internal only"}
{"t":"assume","id":"region","text":"Singapore, one region","alt":"Another region"}
{"t":"assume","id":"scale","text":"About 10k users","alt":"Over 100k users"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"API clients","group":"internet","why":"Web and mobile clients calling the services."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the API domain to the gateway."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"gw","product":"cloud-native-api-gateway","label":"API gateway","group":"vpc","zones":["a","b"],"why":"Single entry point with auth, throttling and routing to services."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"gw","why":"Blocks API attacks and bots at the gateway."}
{"t":"edge","id":"e-users-gw","from":"users","to":"gw","label":"HTTPS"}
{"t":"node","id":"k8s","product":"ack","label":"Microservices cluster","group":"vpc","zones":["a","b"],"why":"Runs the 20 Java services on node pools across two zones."}
{"t":"edge","id":"e-gw-k8s","from":"gw","to":"k8s","label":"routes"}
{"t":"node","id":"registry","product":"mse","label":"Nacos registry & config","group":"vpc","why":"Service discovery and central configuration for all services."}
{"t":"edge","id":"e-k8s-registry","from":"k8s","to":"registry","label":"discovery","kind":"control"}
{"t":"node","id":"mq","product":"rocketmq","label":"Service messaging","group":"vpc","why":"Async events and transactional messages between services."}
{"t":"edge","id":"e-k8s-mq","from":"k8s","to":"mq","kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Cache","group":"vpc","zones":["a","b"],"why":"Caches hot data and sessions for the services."}
{"t":"edge","id":"e-k8s-cache","from":"k8s","to":"cache"}
{"t":"node","id":"db","product":"polardb","label":"Relational DB","group":"vpc","zones":["a","b"],"why":"MySQL-compatible store that scales reads as services grow."}
{"t":"edge","id":"e-k8s-db","from":"k8s","to":"db","label":"SQL"}
{"t":"node","id":"images","product":"acr","label":"Container images","group":"sg","why":"Private registry for the service images."}
{"t":"edge","id":"e-k8s-images","from":"k8s","to":"images","label":"pull","kind":"control"}
{"t":"node","id":"apm","product":"arms","label":"Java APM & tracing","group":"sg","why":"Traces calls across the 20 services."}
{"t":"edge","id":"e-k8s-apm","from":"k8s","to":"apm","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Central container logs and alerts."}
{"t":"edge","id":"e-k8s-logs","from":"k8s","to":"logs","kind":"control"}
{"t":"ask","id":"source","text":"Where do the services run today?","options":["On-premises","Another cloud","New build"]}
{"t":"ask","id":"framework","text":"Which framework do the services use?","options":["Spring Cloud","Dubbo","Plain Spring Boot"]}
{"t":"done","summary":"ACK microservices behind Cloud-native API Gateway with MSE Nacos, RocketMQ, Tair and PolarDB."}

{"t":"say","text":"I'll draw an internal RAG assistant: app on SAE behind an internal ALB, Milvus vectors, documents in OSS, Qwen via Model Studio."}
{"t":"plan","products":["users","vpn-gateway","alb","sae","model-studio","milvus","oss","fc","rds","nat","sls","ram"]}
{"t":"assume","id":"region","text":"Singapore region, new build","alt":"Documents stay on-premises"}
{"t":"assume","id":"scale","text":"About 1k employees","alt":"Over 10k employees"}
{"t":"assume","id":"access","text":"Office access over site-to-site VPN","alt":"Dedicated line via Express Connect"}
{"t":"group","id":"office","kind":"onprem","label":"Company offices","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"office","why":"Staff asking policy and wiki questions from the office network."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"vpn","product":"vpn-gateway","label":"VPN Gateway","group":"vpc","why":"Keeps the assistant private, reachable only from company networks."}
{"t":"node","id":"alb","product":"alb","label":"Internal ALB","group":"vpc","zones":["a","b"],"why":"Private entry point spreading chat requests across zones."}
{"t":"edge","id":"e-users-vpn","from":"users","to":"vpn","label":"IPsec"}
{"t":"edge","id":"e-vpn-alb","from":"vpn","to":"alb","label":"HTTPS"}
{"t":"node","id":"app","product":"sae","label":"Assistant app","group":"vpc","zones":["a","b"],"why":"Runs chat UI and RAG logic: retrieves passages, then prompts Qwen."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"ingest","product":"fc","label":"Document ingestion","group":"sg","why":"Chunks new policy and wiki files, embeds them, writes vectors."}
{"t":"say","text":"Vectors live in Milvus, source files in OSS, chat history in RDS; Qwen calls leave through NAT."}
{"t":"node","id":"vectors","product":"milvus","label":"Vector store","group":"vpc","why":"Finds the policy and wiki passages relevant to each question."}
{"t":"node","id":"db","product":"rds","label":"Chat history DB","group":"vpc","zones":["a","b"],"why":"Stores conversations and feedback for auditing answers."}
{"t":"node","id":"docs","product":"oss","label":"Policy and wiki files","group":"sg","why":"Source documents; uploads trigger re-indexing."}
{"t":"edge","id":"e-app-vectors","from":"app","to":"vectors","label":"search"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"edge","id":"e-docs-ingest","from":"docs","to":"ingest","label":"new files","kind":"async"}
{"t":"edge","id":"e-ingest-vectors","from":"ingest","to":"vectors","label":"upsert"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Outbound path from the VPC to Model Studio APIs."}
{"t":"node","id":"llm","product":"model-studio","label":"Qwen models","group":"sg","why":"Hosted Qwen for answers and embeddings, no GPUs to manage."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat"}
{"t":"edge","id":"e-nat-llm","from":"nat","to":"llm","label":"Qwen API"}
{"t":"edge","id":"e-ingest-llm","from":"ingest","to":"llm","label":"embeddings"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Tracks questions, latency and errors with alerts."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"node","id":"ram","product":"ram","label":"RAM roles","group":null,"why":"Least-privilege roles for the app and ingestion to OSS and Model Studio."}
{"t":"ask","id":"wiki-source","text":"Where does your wiki live today?","options":["Files we can upload to OSS","Confluence or similar SaaS","On-premises servers"]}
{"t":"ask","id":"sso","text":"Should employees sign in with your existing company login?","options":["Yes, SSO required","No, network access is enough"]}
{"t":"done","summary":"Private RAG assistant on SAE behind an internal ALB, with Milvus, OSS and Qwen via Model Studio."}

{"t":"say","text":"For a team, a ready-made assistant fits best: QwenWork for general office work, with Qoder Teams if your team writes code."}
{"t":"rec","product":"qwenwork","fit":"primary","why":"Ready-made workplace agent that drafts docs, slides, sheets and web pages for the whole team."}
{"t":"rec","product":"dingtalk","fit":"complement","why":"Team chat where members reach QwenWork alongside daily collaboration."}
{"t":"rec","product":"qoder-teams","fit":"complement","why":"Coding agent seats with SSO and admin, if developers on the team need one."}
{"t":"edge","id":"e-dingtalk-qwenwork","from":"dingtalk","to":"qwenwork","kind":"data"}
{"t":"ask","id":"audience","text":"Who will mainly use the agent?","options":["Developers","Everyone in the company"]}
{"t":"done","summary":"Recommended QwenWork for the team, with DingTalk and Qoder Teams as complements."}

{"t":"say","text":"For a 20-engineer team using Qwen inside Claude Code and Cursor, Token Plan fits: team seats, per-member keys, predictable subscription."}
{"t":"req","text":"Predictable monthly cost per seat"}
{"t":"rec","product":"token-plan","fit":"primary","why":"Team subscription with per-member keys for Claude Code and Cursor, predictable monthly credits."}
{"t":"rec","product":"qwen-code","fit":"complement","why":"Optional free terminal agent on Qwen models, works with the same Token Plan keys."}
{"t":"say","text":"Token Plan keys are for interactive coding tools only; any app backend should call Model Studio instead."}
{"t":"done","summary":"Recommended Token Plan for 20 engineers using Qwen in Claude Code and Cursor, with Qwen Code as an optional complement."}

{"t":"say","text":"I'll draw three regions (Singapore, Frankfurt, Virginia) behind ESA, with GTM health checks steering traffic and DTS syncing databases."}
{"t":"plan","products":["users","dns","gtm","esa","alb","waf","sae","tair","polardb","dts","sls","cloudmonitor"]}
{"t":"assume","id":"topology","text":"Active-active in all three regions","alt":"Active-passive with one primary region"}
{"t":"assume","id":"stack","text":"Containerized app on SAE, MySQL-compatible data","alt":"Kubernetes on ACK"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"SaaS users (Asia, EU, US)","group":"internet","why":"Customers spread across three continents."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the SaaS domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"node","id":"gtm","product":"gtm","label":"GTM failover","group":null,"why":"Health-checks each region and fails over origins automatically."}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Nearest edge PoP accelerates dynamic and static traffic globally."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"edge","attachTo":"esa","why":"Blocks attacks and bots at the edge for every region."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"say","text":"Each region runs the same stack in two zones: ALB, SAE, Tair and PolarDB."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc-sg","kind":"vpc","label":"Asia VPC","parent":"sg"}
{"t":"node","id":"alb-sg","product":"alb","label":"ALB Asia","group":"vpc-sg","zones":["a","b"],"why":"Regional entry for Asian users across two zones."}
{"t":"node","id":"app-sg","product":"sae","label":"App Asia","group":"vpc-sg","zones":["a","b"],"why":"Autoscaling SaaS app, no servers to manage."}
{"t":"node","id":"cache-sg","product":"tair","label":"Cache Asia","group":"vpc-sg","zones":["a","b"],"why":"Local sessions and hot data for low latency."}
{"t":"node","id":"db-sg","product":"polardb","label":"PolarDB Asia","group":"vpc-sg","zones":["a","b"],"why":"Regional database with in-region zone failover."}
{"t":"edge","id":"e-esa-alb-sg","from":"esa","to":"alb-sg","label":"origin"}
{"t":"edge","id":"e-alb-sg-app-sg","from":"alb-sg","to":"app-sg"}
{"t":"edge","id":"e-app-sg-cache-sg","from":"app-sg","to":"cache-sg"}
{"t":"edge","id":"e-app-sg-db-sg","from":"app-sg","to":"db-sg","label":"SQL"}
{"t":"group","id":"fra","kind":"region","label":"Frankfurt (eu-central-1)","parent":null}
{"t":"group","id":"vpc-fra","kind":"vpc","label":"Europe VPC","parent":"fra"}
{"t":"node","id":"alb-fra","product":"alb","label":"ALB Europe","group":"vpc-fra","zones":["a","b"],"why":"Regional entry for European users across two zones."}
{"t":"node","id":"app-fra","product":"sae","label":"App Europe","group":"vpc-fra","zones":["a","b"],"why":"Same app serving Europe, scales by itself."}
{"t":"node","id":"cache-fra","product":"tair","label":"Cache Europe","group":"vpc-fra","zones":["a","b"],"why":"Local sessions and hot data for low latency."}
{"t":"node","id":"db-fra","product":"polardb","label":"PolarDB Europe","group":"vpc-fra","zones":["a","b"],"why":"Regional database with in-region zone failover."}
{"t":"edge","id":"e-esa-alb-fra","from":"esa","to":"alb-fra","label":"origin"}
{"t":"edge","id":"e-alb-fra-app-fra","from":"alb-fra","to":"app-fra"}
{"t":"edge","id":"e-app-fra-cache-fra","from":"app-fra","to":"cache-fra"}
{"t":"edge","id":"e-app-fra-db-fra","from":"app-fra","to":"db-fra","label":"SQL"}
{"t":"group","id":"us","kind":"region","label":"Virginia (us-east-1)","parent":null}
{"t":"group","id":"vpc-us","kind":"vpc","label":"US VPC","parent":"us"}
{"t":"node","id":"alb-us","product":"alb","label":"ALB US","group":"vpc-us","zones":["a","b"],"why":"Regional entry for US users across two zones."}
{"t":"node","id":"app-us","product":"sae","label":"App US","group":"vpc-us","zones":["a","b"],"why":"Same app serving the US, scales by itself."}
{"t":"node","id":"cache-us","product":"tair","label":"Cache US","group":"vpc-us","zones":["a","b"],"why":"Local sessions and hot data for low latency."}
{"t":"node","id":"db-us","product":"polardb","label":"PolarDB US","group":"vpc-us","zones":["a","b"],"why":"Regional database with in-region zone failover."}
{"t":"edge","id":"e-esa-alb-us","from":"esa","to":"alb-us","label":"origin"}
{"t":"edge","id":"e-alb-us-app-us","from":"alb-us","to":"app-us"}
{"t":"edge","id":"e-app-us-cache-us","from":"app-us","to":"cache-us"}
{"t":"edge","id":"e-app-us-db-us","from":"app-us","to":"db-us","label":"SQL"}
{"t":"edge","id":"e-gtm-alb-sg","from":"gtm","to":"alb-sg","label":"health check","kind":"control"}
{"t":"edge","id":"e-gtm-alb-fra","from":"gtm","to":"alb-fra","label":"health check","kind":"control"}
{"t":"edge","id":"e-gtm-alb-us","from":"gtm","to":"alb-us","label":"health check","kind":"control"}
{"t":"say","text":"DTS keeps the three databases in sync so any region can take over."}
{"t":"node","id":"dts","product":"dts","label":"Cross-region sync","group":null,"why":"Two-way replication between regional databases for failover."}
{"t":"edge","id":"e-db-sg-dts","from":"db-sg","to":"dts","label":"sync","kind":"async"}
{"t":"edge","id":"e-db-fra-dts","from":"db-fra","to":"dts","label":"sync","kind":"async"}
{"t":"edge","id":"e-db-us-dts","from":"db-us","to":"dts","label":"sync","kind":"async"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Central logs and alerts across regions."}
{"t":"node","id":"monitor","product":"cloudmonitor","label":"CloudMonitor","group":null,"why":"Regional metrics and alarms that confirm failovers."}
{"t":"edge","id":"e-app-sg-logs","from":"app-sg","to":"logs","kind":"control"}
{"t":"edge","id":"e-app-fra-logs","from":"app-fra","to":"logs","kind":"control"}
{"t":"edge","id":"e-app-us-logs","from":"app-us","to":"logs","kind":"control"}
{"t":"ask","id":"residency","text":"Must customer data stay in its home region (for example EU data in Frankfurt)?","options":["Yes, per-region residency","No, replicate everywhere"]}
{"t":"ask","id":"write-model","text":"Can each region accept writes, or should one region own writes?","options":["Writes in every region","One primary write region"]}
{"t":"done","summary":"Three-region SaaS behind ESA with WAF, GTM failover, SAE, Tair and PolarDB per region, synced by DTS."}

{"t":"say","text":"I'll put ESA with WAF in front of your site, and add Captcha and Fraud Detection on sign-up and login."}
{"t":"plan","products":["users","dns","esa","waf","alb","ecs","captcha","fraud-detection","sls"]}
{"t":"assume","id":"hosting","text":"Site already runs on Alibaba Cloud in Singapore","alt":"Site runs on another cloud or on-premises"}
{"t":"assume","id":"ddos-size","text":"ESA built-in DDoS defense covers the attacks","alt":"Very large attacks need Anti-DDoS Proxy"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers and bots","group":"internet","why":"Real shoppers mixed with bot and attack traffic."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Points the shop domain at ESA so the origin stays hidden."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Absorbs DDoS floods and filters bots at the edge."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"edge","attachTo":"esa","why":"Rate-limits login attempts and blocks credential stuffing patterns."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Shop VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"Existing ALB","group":"vpc","zones":["a","b"],"why":"Your current entry point, now reachable only from ESA."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"Existing shop servers","group":"vpc","zones":["a","b"],"why":"Your shop app, which calls the risk checks on sign-up and login."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sign-up and login forms get a Captcha challenge, and Fraud Detection scores each attempt."}
{"t":"node","id":"captcha","product":"captcha","label":"Captcha","group":"sg","why":"Challenges suspicious sign-ups and logins to stop automated bots."}
{"t":"node","id":"fraud","product":"fraud-detection","label":"Fraud Detection","group":"sg","why":"Scores fake sign-ups and account takeover attempts before accepting them."}
{"t":"edge","id":"e-app-captcha","from":"app","to":"captcha","label":"verify"}
{"t":"edge","id":"e-app-fraud","from":"app","to":"fraud","label":"risk score"}
{"t":"node","id":"logs","product":"sls","label":"Security logs","group":"sg","why":"Collects ESA and app logs to spot attacks and tune rules."}
{"t":"edge","id":"e-esa-logs","from":"esa","to":"logs","kind":"control"}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"hosting-where","text":"Where does your shop run today?","options":["Alibaba Cloud","Another cloud","On-premises"]}
{"t":"ask","id":"attack-size","text":"How large have the DDoS attacks been?","options":["Small, occasional","Large, sustained"]}
{"t":"done","summary":"ESA with WAF against DDoS and credential stuffing, plus Captcha and Fraud Detection on sign-up and login."}

{"t":"say","text":"I recommend Elastic Desktop Service (EDS) Enterprise for the 50 contractors, with SSO and MFA, and shared files that stay in your cloud."}
{"t":"req","text":"Company data never leaves our cloud"}
{"t":"req","text":"Secure cloud desktops for 50 contractors"}
{"t":"rec","product":"eds","fit":"primary","why":"Contractors work in cloud desktops; clipboard, download and USB policies keep data from leaving."}
{"t":"rec","product":"idaas","fit":"complement","why":"Gives contractors SSO and MFA, and access ends cleanly when contracts end."}
{"t":"rec","product":"nas","fit":"complement","why":"Shared project files mounted on desktops, stored only inside your VPC."}
{"t":"rec","product":"actiontrail","fit":"complement","why":"Audits admin and API actions on the desktop environment for compliance reviews."}
{"t":"ask","id":"contractor-access","text":"Do contractors need private access to apps in your VPC or on-premises?","options":["Only cloud apps","On-premises systems too","No internal apps"]}
{"t":"done","summary":"Recommended EDS Enterprise with IDaaS, NAS and ActionTrail so contractor data stays in the cloud."}

{"t":"say","text":"Tongyi Lingma is now Qoder; for 10 developers I recommend Qoder Teams seats with SSO and admin controls."}
{"t":"req","text":"10 developers in Singapore"}
{"t":"rec","product":"qoder-teams","fit":"primary","why":"Team seats for your 10 developers with SSO, privacy mode and usage analytics."}
{"t":"rec","product":"marketplace","fit":"complement","why":"Buy Qoder Teams seats through Alibaba Cloud billing."}
{"t":"done","summary":"Recommended Qoder Teams (formerly Tongyi Lingma) for 10 developers, purchasable via Marketplace."}

{"t":"say","text":"I'll add WAF 3.0 in cloud-native mode as a badge on the ALB, inspecting all store traffic before it reaches the app servers."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks OWASP attacks, CC floods and scraping bots before the app servers."}
{"t":"done","summary":"Added WAF 3.0 as a badge on the ALB to protect the store."}

{"t":"say","text":"I'll swap the ECS app tier for ACK across two zones, and remove Auto Scaling since ACK scales pods and nodes itself."}
{"t":"req","text":"Run the app tier on Kubernetes"}
{"t":"node","id":"app","product":"ack","label":"App cluster","group":"vpc","zones":["a","b"],"why":"Runs store services as pods in two zones; autoscales pods and node pools."}
{"t":"remove","id":"scaling"}
{"t":"done","summary":"App tier now runs on ACK in two zones, keeping existing edges, with Auto Scaling removed."}

{"t":"say","text":"ApsaraDB for Redis is now Tair (Redis® OSS-Compatible). I'll draw a two-zone Tair cache next to your existing web app."}
{"t":"plan","products":["ecs","tair","cloudmonitor"]}
{"t":"assume","id":"app-location","text":"Web app already runs on ECS in Singapore","alt":"Web app runs on-premises"}
{"t":"assume","id":"region","text":"Singapore (ap-southeast-1)","alt":"Another region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"App VPC","parent":"sg"}
{"t":"node","id":"app","product":"ecs","label":"Existing web app","group":"vpc","why":"Your current app servers, which read and write cached data."}
{"t":"node","id":"cache","product":"tair","label":"Tair cache","group":"vpc","zones":["a","b"],"why":"Caches sessions and hot queries; replica in second zone fails over automatically."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache","label":"Redis protocol"}
{"t":"node","id":"monitor","product":"cloudmonitor","label":"CloudMonitor","group":"sg","why":"Alerts on cache memory, hit rate and connection limits."}
{"t":"edge","id":"e-cache-monitor","from":"cache","to":"monitor","kind":"control"}
{"t":"ask","id":"app-host","text":"Where does your web app run today?","options":["Alibaba Cloud ECS","Other Alibaba service","On-premises","Another cloud"]}
{"t":"done","summary":"Two-zone Tair (Redis® OSS-Compatible) cache beside the existing web app in a Singapore VPC, with CloudMonitor alerts."}

{"t":"say","text":"Removing the AI shopping assistant: Model Studio and the Milvus product vectors go; search, images and the store stay."}
{"t":"remove","id":"assistant"}
{"t":"remove","id":"vectors"}
{"t":"done","summary":"Removed the shopping assistant (Model Studio) and its Milvus vector store; the rest of the store is unchanged."}

{"t":"say","text":"Restoring the AI shopping assistant: Qwen on Model Studio and the Milvus product vectors, with their original links."}
{"t":"node","id":"assistant","product":"model-studio","label":"Shopping assistant (Qwen)","group":"sg","why":"Answers shopper questions with hosted Qwen models."}
{"t":"node","id":"vectors","product":"milvus","label":"Product vectors","group":"vpc","why":"Retrieves matching products to ground assistant answers."}
{"t":"edge","id":"e-app-assistant","from":"app","to":"assistant","label":"chat API"}
{"t":"edge","id":"e-app-vectors","from":"app","to":"vectors","label":"retrieve"}
{"t":"done","summary":"Restored the shopping assistant on Model Studio with Milvus product vectors and their original edges."}

{"t":"say","text":"Sydney (ap-southeast-2) is closed, so I'll draw the web app in Singapore with ESA edge acceleration for Australian customers."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","oss","sls","nat"]}
{"t":"assume","id":"scale","text":"About 10k customers","alt":"Over 100k customers"}
{"t":"assume","id":"build","text":"New build on Alibaba Cloud","alt":"Migrating from another cloud"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Australian customers","group":"internet","why":"Customers in Australia using the web app."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the app domain to ESA."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
